//! rtg.library's functions for drivers: what a display's or a bus's
//! driver calls, as the library's second interface. The base is the one
//! OpenLibrary("rtg.library", 1) answers, seen as an RtgDriverBase; its
//! slots follow those of the programs' interface, sdk/fd/rtg_lib.fd, in
//! the one jump table.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/rtgdriver_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const utility = @import("../libs/utility/utility.zig");
const rtg = @import("../libs/rtg/rtg.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "rtg.library";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const AddRtgDriver = libraries.lvo(72);
    pub const RemRtgDriver = libraries.lvo(73);
    pub const SignalRtgEvent = libraries.lvo(74);
    pub const TxParam = libraries.lvo(75);
    pub const TxColor = libraries.lvo(76);
    pub const RxParam = libraries.lvo(77);
    pub const GetRtgTagData = libraries.lvo(78);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const AddRtgDriver = *const fn (*RtgDriverBase, *const rtg.RtgDriverSpec, ?*anyopaque) callconv(.c) ?*rtg.RtgDriver;
    pub const RemRtgDriver = *const fn (*RtgDriverBase, *rtg.RtgDriver) callconv(.c) bool;
    pub const SignalRtgEvent = *const fn (*RtgDriverBase, *rtg.RtgBoard, u32) callconv(.c) i32;
    pub const TxParam = *const fn (*RtgDriverBase, *rtg.RtgTransport, i32, ?*const anyopaque, u32) callconv(.c) i32;
    pub const TxColor = *const fn (*RtgDriverBase, *rtg.RtgTransport, i32, ?*const anyopaque, u32) callconv(.c) i32;
    pub const RxParam = *const fn (*RtgDriverBase, *rtg.RtgTransport, i32, ?*anyopaque, u32) callconv(.c) i32;
    pub const GetRtgTagData = *const fn (*RtgDriverBase, utility.Tag, usize, ?[*]const utility.TagItem) callconv(.c) usize;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const RtgDriverBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *RtgDriverBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// Put a driver's description on the list: the library makes the
    /// driver's node, with the state the description asks for behind it,
    /// cleared. `seg_list` is the segments of a driver that was loaded, null
    /// for one in ROM. Null for a name already there, for ops that fill in
    /// neither create, or without memory. Not from interrupts.
    pub fn AddRtgDriver(self: *RtgDriverBase, spec: *const rtg.RtgDriverSpec, seg_list: ?*anyopaque) ?*rtg.RtgDriver {
        return libraries.call(self, LVO.AddRtgDriver, Fn.AddRtgDriver, .{ spec, seg_list });
    }

    /// Take a driver off the list and free its node and its state. False
    /// while a board or a bus it made is still alive, and for one that is not
    /// on the list. Not from interrupts.
    pub fn RemRtgDriver(self: *RtgDriverBase, driver: *rtg.RtgDriver) bool {
        return libraries.call(self, LVO.RemRtgDriver, Fn.RemRtgDriver, .{driver});
    }

    /// Tell a board's servers that something happened. A driver calls it from
    /// its own interrupt; returns what the chain answered.
    pub fn SignalRtgEvent(self: *RtgDriverBase, board: *rtg.RtgBoard, event: u32) i32 {
        return libraries.call(self, LVO.SignalRtgEvent, Fn.SignalRtgEvent, .{ board, event });
    }

    /// A command and its parameters to the part. A command below zero sends
    /// the parameters alone.
    pub fn TxParam(self: *RtgDriverBase, io: *rtg.RtgTransport, cmd: i32, param: ?*const anyopaque, size: u32) i32 {
        return libraries.call(self, LVO.TxParam, Fn.TxParam, .{ io, cmd, param, size });
    }

    /// A command and a run of pixels. It comes back when the bytes have gone.
    pub fn TxColor(self: *RtgDriverBase, io: *rtg.RtgTransport, cmd: i32, color: ?*const anyopaque, size: u32) i32 {
        return libraries.call(self, LVO.TxColor, Fn.TxColor, .{ io, cmd, color, size });
    }

    /// Send a command and read `size` bytes back, with nothing else reaching
    /// the bus in between.
    pub fn RxParam(self: *RtgDriverBase, io: *rtg.RtgTransport, cmd: i32, buffer: ?*anyopaque, size: u32) i32 {
        return libraries.call(self, LVO.RxParam, Fn.RxParam, .{ io, cmd, buffer, size });
    }

    /// A tag's data, or `default_value` if it is not in the list. Here so a
    /// driver need open nothing but this library.
    pub fn GetRtgTagData(self: *RtgDriverBase, tag_value: utility.Tag, default_value: usize, tag_list: ?[*]const utility.TagItem) usize {
        return libraries.call(self, LVO.GetRtgTagData, Fn.GetRtgTagData, .{ tag_value, default_value, tag_list });
    }
};
